    ratios = []
    for leaf, gross in plan['leaf_req'].items():
        if gross <= 1e-12:
            continue
        avail = leaf_total_available(leaf, st)
        ratios.append((avail / gross, leaf))
    for wc, gross in plan['hours_req'].items():
        if gross <= 1e-12:
            continue
        avail = st['wc_avail'].get(wc, 0.0)
        ratios.append((avail / gross, wc))
    below = [(r, res) for r, res in ratios if r < 1.0 - 1e-12]
    if not below:
        return None
    min_r = min(r for r, _ in below)
    tied = [res for r, res in below if abs(r - min_r) < 1e-12]
    return sorted(tied)[0]


